    "predicted_outcome": {
      "supported": 0.05,
      "rejected": 0.1,
      "untestable": 0.7,
      "artifact": 0.1,
      "uncertain": 0.05
    },
    "decision": "do_not_proceed",
    "design": {
      "estimand": "The causal effect of a teammate DRIVE occurring in the immediately preceding possession (by the same team) on points per possession of a subsequent PNR, compared to PNR preceded by a different play type, conditional on defensive coverage and shot-clock state.",
      "unit": "possession",
      "sample": "NBA 2023-24 and 2024-25 regular seasons, using only possessions where PNR is confidently labelled and the prior possession ends in a play-type that can be verified (post-label validation).",
      "power": "Not computable with current label quality; a minimum of 5000 matched pairs would be needed to detect 0.05 PPP with 80% power, but label noise would drastically reduce effective sample.",
